#include "opensim/scene/task_inventory_remove.hpp"
#include <iostream>
using namespace opensim;using namespace scene;
namespace {
framework::Uuid id(int n){auto t=std::to_string(n);return framework::Uuid("11223344-5566-7788-99aa-"+std::string(12-t.size(),'0')+t);}
std::string probe(int mode,int failure){std::string trace;bool present=true;int serial=0,get_count=0;auto item=std::make_shared<framework::TaskInventoryItem>([]{return 111;});item->item_id=id(2);item->type=(mode&128)?7:10;
 auto step=[&](int point,std::string s){trace+="|"+s;if(point==failure)throw std::runtime_error("injected");};TaskInventoryRemoveBackend b;
 b.part=[&](auto local)->std::optional<TaskInventoryRemovePart>{step(1,"PART:"+std::to_string(local));if(mode&1)return {};return TaskInventoryRemovePart{id(3),!(mode&2)};};b.can_edit=[&](auto p,auto a){step(2,"EDIT:"+p.str()+":"+a.str());return !(mode&4);};
 b.group_item=[&](auto p,auto local,auto key){++get_count;step(get_count==1?3:13,"GET:"+p.id.str()+":"+std::to_string(local)+":"+key.str());if((mode&8)||!present)return std::shared_ptr<framework::TaskInventoryItem>{};if(get_count>1&&(mode&4096)){auto other=std::make_shared<framework::TaskInventoryItem>(item->clone());other->type=other->type==10?7:10;return other;}return item;};
 b.trash_folder=[&](auto a)->std::optional<framework::Uuid>{step(4,"TRASH:"+a.str()+":14");if(mode&16)return {};return id(4);};b.move_to_user=[&](const auto& c,auto folder,auto p,auto key){step(5,"MOVE:"+c.agent.str()+":"+folder.str()+":"+p.id.str()+":"+key.str());if(mode&64)present=false;if(mode&256)item->type=item->type==10?7:10;return TaskInventoryMoveResult{!(mode&32),(mode&512)?std::optional<std::string>{}:std::optional<std::string>("failure")};};
 b.warn=[&](auto key,const auto& msg){step(6,"WARN:"+key.str()+":"+msg.value_or("NULL"));};b.remove_script_events=[&](auto p,auto key){step(8,"EVENTS:"+p.id.str()+":"+key.str());};b.active_script_count=[&](auto p,int count){step(9,"ACTIVE:"+p.id.str()+":"+std::to_string(count));};b.group_remove=[&](auto p,auto local,auto key){step(10,"REMOVE:"+p.id.str()+":"+std::to_string(local)+":"+key.str());present=false;++serial;};b.invalidate_effective=[&](auto p){step(11,"PERMS:"+p.id.str());};b.properties=[&](auto p,const auto& c){step(12,"PROPS:"+p.id.str()+":"+c.agent.str());};TaskInventoryRemoveClient client{id(1),[&](const auto& msg,bool modal){step(7,"ALERT:"+msg.value_or("NULL")+":"+(modal?"1":"0"));}};
 TaskInventoryRemoveController controller(std::move(b));std::string result="OK";try{controller.remove(client,(mode&1024)?framework::Uuid{}:id(2),(mode&2048)?0u:123u);}catch(...){result="THROW";}return result+":"+(present?"1":"0")+":"+std::to_string(serial)+trace;
}
}
int main(int argc,char**argv){try{if(argc>1&&std::string_view(argv[1])=="--probe"){int m,f;while(std::cin>>m>>f)std::cout<<probe(m,f)<<'\n';return 0;}int count=0;auto check=[&](bool v,const char*s){++count;if(!v)throw std::runtime_error(s);};check(probe(0,0).starts_with("OK:0:1"),"copyable move thenremove");check(probe(64,0).starts_with("OK:0:0"),"movealreadyremoved skipouterremove");check(probe(32,0).find("|WARN:")!=std::string::npos&&probe(32,0).find("PROPS:")==std::string::npos,"failure alerts withoutdelete/properties");check(probe(16,0).starts_with("THROW:1:0"),"missingtrash throws");check(probe(128,0).find("|EVENTS:")==std::string::npos,"typeusesAssetType");check(probe(2,0).find("EDIT:")==std::string::npos,"groupbeforepermission");check(probe(0,5).starts_with("THROW:1:0"),"moveexceptionnodelete");std::cout<<"PASS: "<<count<<" task inventory removal checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
